CREATE TABLE `resposta_pesquisa` (
  `ID_RESPOSTA` int NOT NULL AUTO_INCREMENT,
  `ID_CICLO` int NOT NULL,
  `ID_PERGUNTA` int NOT NULL,
  `ID_DEPARTAMENTO` int NOT NULL COMMENT 'FK para cadastro_geral.departamento',
  `ID_AREA` int NOT NULL COMMENT 'FK para cadastro_geral.area',
  `NOTA` tinyint NOT NULL COMMENT 'Escala de 1 a 5',
  `COMENTARIO` text COMMENT 'Campo de texto livre opcional',
  `DATA_RESPOSTA` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID_RESPOSTA`),
  KEY `fk_resposta_ciclo` (`ID_CICLO`),
  KEY `fk_resposta_pergunta` (`ID_PERGUNTA`),
  KEY `idx_resposta_depto` (`ID_DEPARTAMENTO`),
  KEY `idx_resposta_area` (`ID_AREA`),
  CONSTRAINT `fk_resposta_ciclo` FOREIGN KEY (`ID_CICLO`) REFERENCES `ciclo_pesquisa` (`ID_CICLO`),
  CONSTRAINT `fk_resposta_pergunta` FOREIGN KEY (`ID_PERGUNTA`) REFERENCES `pergunta_pesquisa` (`ID_PERGUNTA`),
  CONSTRAINT `chk_nota_range` CHECK ((`NOTA` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=8501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Respostas anônimas — sem vínculo direto ao funcionário';
